# Tab completion for bxSites, for PowerShell 5.1 and 7+.
# Generated by tools/generate-completions.bxs from the verb table in ModuleConfig.bx, do not edit.
# Load it from your profile ($PROFILE):
#   . "<module folder>\completions\bxSites.ps1"

Register-ArgumentCompleter -Native -CommandName 'bxSites', 'bxsites' -ScriptBlock {
	param( $wordToComplete, $commandAst, $cursorPosition )

	$verbs = @{
		'agents:sync' = '(Re)write AGENTS.md/.markdownlint.json'
		'audit' = 'CI-grade content check on a built site: broken links/images, missing alt text, orphaned...'
		'blog:drafts' = 'List every blog post whose frontmatter sets draft: true'
		'blog:find' = 'Filter blog posts'
		'build' = 'Render docs/**.md into a static site in site/'
		'clean' = 'Remove site/ and any build cache'
		'coldbox' = 'Document a ColdBox application from its conventions on disk: routes, handlers, models,...'
		'deploy' = 'Build and ship site/ to a real target: s3, azure, gcs, firebase, ftp, sftp, rsync,...'
		'docbox' = 'Generate a BoxLang/CFML API reference from DocBox into the content dir; needs the...'
		'doctor' = 'Check the project/environment for common problems'
		'gh-deploy' = 'Build and force-push site/ to a gh-pages branch'
		'i18n:new' = 'Scaffold a new docs/i18n/<code> locale'
		'i18n:status' = 'Report per-locale translation coverage against the default tree'
		'install:plugin' = 'Download a plugin from ForgeBox into boxlang_modules/'
		'install:theme' = 'Download a theme from ForgeBox into your content root''s .themes/<name>/'
		'layout:new' = 'Scaffold a named layout in .overrides/<theme>/ by copying a template of the active theme'
		'lint' = 'Pre-build content checks: heading level skips, blog posts missing a valid date'
		'migrate' = 'Convert a GitBook export, mkdocs project, plain zip of Markdown, or Notion export into a...'
		'new' = 'Scaffold a new project'
		'package' = 'Build and zip site/ into a single archive'
		'page:new' = 'Scaffold a single docs page at an arbitrary path'
		'page:rename' = 'Move a docs page and rewrite every relative link that pointed at it'
		'plugin:new' = 'Scaffold a plugin module skeleton'
		'post:new' = 'Scaffold a new blog post'
		'publish' = 'Build and publish site/ to bxSites Cloud, using [cloud.siteId]/[cloud.apiUrl] in...'
		'search-index' = 'Rebuild the search index standalone'
		'search:query' = 'Query a built search-index.json and rank results'
		'serve' = 'Build and serve the site locally with live reload'
		'skills:install' = 'Install the bx-sites AI agent skills'
		'stats' = 'Report page/word counts, versions/locales, blog, tags, search index, and site size for a...'
		'theme:import' = 'Best-effort convert a mkdocs/jekyll/hugo theme into your content root''s .themes/<name>/'
		'theme:new' = 'Eject a built-in theme into your content root''s .theme/ for customizing'
		'version:new' = 'Snapshot docs/ into a new docs/versions/<name>/'
		'help' = 'Show the usage and the list of verbs'
	}
	$options = @{
		'agents:sync' = @(
			@{ Name = 'agents'; Value = $true; Choices = @('agents', 'none'); File = $false }
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); File = $true }
		)
		'audit' = @(
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); File = $true }
		)
		'blog:drafts' = @(
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); File = $true }
		)
		'blog:find' = @(
			@{ Name = 'author'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'category'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'tag'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'since'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'until'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'drafts'; Value = $false; Choices = @(); File = $false }
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); File = $true }
		)
		'build' = @(
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); File = $true }
		)
		'clean' = @(
			@{ Name = 'force'; Value = $false; Choices = @(); File = $false }
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); File = $true }
		)
		'coldbox' = @(
			@{ Name = 'appRoot'; Value = $true; Choices = @(); File = $true }
			@{ Name = 'pagePathPrefix'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'tags'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'include'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); File = $true }
		)
		'deploy' = @(
			@{ Name = 'entry'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'target'; Value = $true; Choices = @('s3', 'azure', 'gcs', 'firebase', 'ftp', 'sftp', 'rsync', 'netlify', 'vercel', 'cloudflare-pages', 'local', 'github-pages'); File = $false }
			@{ Name = 'verbose'; Value = $false; Choices = @(); File = $false }
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); File = $true }
		)
		'docbox' = @(
			@{ Name = 'mappings:'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'projectTitle'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'excludes'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'pagePathPrefix'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'tags'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'jsonDir'; Value = $true; Choices = @(); File = $true }
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); File = $true }
		)
		'doctor' = @(
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); File = $true }
		)
		'gh-deploy' = @(
			@{ Name = 'branch'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'remote'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'message'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); File = $true }
		)
		'i18n:new' = @(
			@{ Name = 'code'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); File = $true }
		)
		'i18n:status' = @(
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); File = $true }
		)
		'install:plugin' = @(
			@{ Name = 'name'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'version'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); File = $true }
		)
		'install:theme' = @(
			@{ Name = 'name'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'version'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); File = $true }
		)
		'layout:new' = @(
			@{ Name = 'name'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'from'; Value = $true; Choices = @('page'); File = $false }
			@{ Name = 'theme'; Value = $true; Choices = @('bootstrap', 'docsy', 'docusaurus', 'gitbook', 'justthedocs', 'material', 'notion', 'slate', 'tailwind', 'vuepress'); File = $false }
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); File = $true }
		)
		'lint' = @(
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); File = $true }
		)
		'migrate' = @(
			@{ Name = 'source'; Value = $true; Choices = @(); File = $true }
			@{ Name = 'from'; Value = $true; Choices = @('gitbook', 'mkdocs', 'markdown-zip', 'notion'); File = $false }
			@{ Name = 'force'; Value = $false; Choices = @(); File = $false }
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); File = $true }
		)
		'new' = @(
			@{ Name = 'theme'; Value = $true; Choices = @('bootstrap', 'docsy', 'docusaurus', 'gitbook', 'justthedocs', 'material', 'notion', 'slate', 'tailwind', 'vuepress'); File = $false }
			@{ Name = 'name'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'source'; Value = $true; Choices = @('docs', 'src'); File = $false }
			@{ Name = 'docs'; Value = $false; Choices = @(); File = $false }
			@{ Name = 'site'; Value = $false; Choices = @(); File = $false }
			@{ Name = 'agents'; Value = $true; Choices = @('agents', 'none'); File = $false }
			@{ Name = 'description'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'format'; Value = $true; Choices = @('yaml', 'toml', 'json'); File = $false }
			@{ Name = 'no-agents'; Value = $false; Choices = @(); File = $false }
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); File = $true }
		)
		'new:positional' = 'dir'
		'package' = @(
			@{ Name = 'output'; Value = $true; Choices = @(); File = $true }
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); File = $true }
		)
		'page:new' = @(
			@{ Name = 'path'; Value = $true; Choices = @(); File = $true }
			@{ Name = 'title'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'description'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'icon'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'tags'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'order'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); File = $true }
		)
		'page:rename' = @(
			@{ Name = 'from'; Value = $true; Choices = @(); File = $true }
			@{ Name = 'to'; Value = $true; Choices = @(); File = $true }
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); File = $true }
		)
		'plugin:new' = @(
			@{ Name = 'name'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'dest'; Value = $true; Choices = @(); File = $true }
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); File = $true }
		)
		'post:new' = @(
			@{ Name = 'title'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'slug'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'date'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'authors'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'categories'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'tags'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'draft'; Value = $false; Choices = @(); File = $false }
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); File = $true }
		)
		'publish' = @(
			@{ Name = 'token'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); File = $true }
		)
		'search-index' = @(
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); File = $true }
		)
		'search:query' = @(
			@{ Name = 'query'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'limit'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); File = $true }
		)
		'serve' = @(
			@{ Name = 'port'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'host'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); File = $true }
		)
		'skills:install' = @(
			@{ Name = 'skill'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); File = $true }
		)
		'stats' = @(
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); File = $true }
		)
		'theme:import' = @(
			@{ Name = 'source'; Value = $true; Choices = @(); File = $true }
			@{ Name = 'path'; Value = $true; Choices = @(); File = $true }
			@{ Name = 'name'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'force'; Value = $false; Choices = @(); File = $false }
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); File = $true }
		)
		'theme:new' = @(
			@{ Name = 'theme'; Value = $true; Choices = @('bootstrap', 'docsy', 'docusaurus', 'gitbook', 'justthedocs', 'material', 'notion', 'slate', 'tailwind', 'vuepress'); File = $false }
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); File = $true }
		)
		'version:new' = @(
			@{ Name = 'name'; Value = $true; Choices = @(); File = $false }
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); File = $true }
		)
		'help' = @(
		)
		'help:positional' = 'verbs'
	}
	$globals = @( '--help', '-h', '--version', '-v' )

	# the words typed before the one under the cursor (the command name is the first); an empty word is not in the AST
	$typed = @( $commandAst.CommandElements | ForEach-Object { $_.ToString() } )
	if ( $wordToComplete -ne '' ) {
		$typed = @( $typed | Select-Object -SkipLast 1 )
	}

	function New-BxSitesResult( [string] $Text, [string] $Tip ) {
		if ( -not $Tip ) { $Tip = $Text }
		[System.Management.Automation.CompletionResult]::new( $Text, $Text, 'ParameterValue', $Tip )
	}

	# bxSites <verb>
	if ( $typed.Count -le 1 ) {
		if ( $wordToComplete -like '-*' ) {
			foreach ( $g in $globals ) {
				if ( $g -like "$wordToComplete*" ) { New-BxSitesResult $g }
			}
		} else {
			foreach ( $name in ( @( $verbs.Keys ) | Sort-Object ) ) {
				if ( $name -like "$wordToComplete*" ) { New-BxSitesResult $name $verbs[ $name ] }
			}
		}
		return
	}

	# bxSites page <new|rename>: a colon verb written as two words
	if ( $typed.Count -eq 2 -and -not $verbs.ContainsKey( $typed[ 1 ] ) -and $wordToComplete -notlike '-*' ) {
		foreach ( $name in ( @( $verbs.Keys ) | Sort-Object ) ) {
			if ( $name -like "$( $typed[ 1 ] ):$wordToComplete*" ) {
				$second = $name.Substring( $typed[ 1 ].Length + 1 )
				New-BxSitesResult $second $verbs[ $name ]
			}
		}
		return
	}

	$verb = $typed[ 1 ]
	if ( $typed.Count -ge 3 -and $verbs.ContainsKey( "$( $typed[ 1 ] ):$( $typed[ 2 ] )" ) ) {
		$verb = "$( $typed[ 1 ] ):$( $typed[ 2 ] )"
	}
	$verbOptions = if ( $options.ContainsKey( $verb ) ) { @( $options[ $verb ] ) } else { @() }

	# --flag=<value>
	if ( $wordToComplete -match '^(--[^=]+)=(.*)$' ) {
		$flag = $Matches[ 1 ]
		$part = $Matches[ 2 ]
		$option = $verbOptions | Where-Object { "--$( $_.Name )" -eq $flag } | Select-Object -First 1
		if ( $option -and $option.Choices.Count ) {
			foreach ( $choice in $option.Choices ) {
				if ( $choice -like "$part*" ) { New-BxSitesResult "$flag=$choice" $choice }
			}
		} elseif ( $option -and $option.File ) {
			foreach ( $item in @( Get-ChildItem -Path "$part*" -ErrorAction SilentlyContinue ) ) {
				$path = Resolve-Path -LiteralPath $item.FullName -Relative
				if ( $item.PSIsContainer ) { $path += [System.IO.Path]::DirectorySeparatorChar }
				if ( $path -match '\s' ) { $path = "'$path'" }
				New-BxSitesResult "$flag=$path" $path
			}
		}
		return
	}

	# --flag
	if ( $wordToComplete -like '-*' ) {
		foreach ( $option in $verbOptions ) {
			$text = if ( $option.Value -and -not $option.Name.EndsWith( ':' ) ) { "--$( $option.Name )=" } else { "--$( $option.Name )" }
			if ( $text -like "$wordToComplete*" ) { New-BxSitesResult $text }
		}
		foreach ( $g in $globals ) {
			if ( $g -like "$wordToComplete*" ) { New-BxSitesResult $g }
		}
		return
	}

	# the argument that follows the verb
	switch ( $options[ "${verb}:positional" ] ) {
		'dir' {
			foreach ( $item in @( Get-ChildItem -Directory -Path "$wordToComplete*" -ErrorAction SilentlyContinue ) ) {
				$path = ( Resolve-Path -LiteralPath $item.FullName -Relative ) + [System.IO.Path]::DirectorySeparatorChar
				if ( $path -match '\s' ) { $path = "'$path'" }
				New-BxSitesResult $path
			}
		}
		'verbs' {
			foreach ( $name in ( @( $verbs.Keys ) | Sort-Object ) ) {
				if ( $name -like "$wordToComplete*" ) { New-BxSitesResult $name $verbs[ $name ] }
			}
		}
	}
}
